function fewestTreats(ratings: number[]): number {
  const n = ratings.length, t = new Array(n).fill(1);
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i < n; i++) {
      if (i > 0 && ratings[i] > ratings[i - 1] && t[i] <= t[i - 1]) { t[i] = t[i - 1] + 1; changed = true; }
      if (i < n - 1 && ratings[i] > ratings[i + 1] && t[i] <= t[i + 1]) { t[i] = t[i + 1] + 1; changed = true; }
    }
  }
  return t.reduce((a, b) => a + b, 0);
}

