function fewestTreats(ratings: number[]): number {
  const n = ratings.length, left = new Array(n).fill(1);
  for (let i = 1; i < n; i++) {
    if (ratings[i] > ratings[i - 1]) left[i] = left[i - 1] + 1;
  }
  let total = left[n - 1], right = 1;
  for (let i = n - 2; i >= 0; i--) {
    right = ratings[i] > ratings[i + 1] ? right + 1 : 1;
    total += Math.max(left[i], right);
  }
  return total;
}

